  var model = core.make({"id":"eclampsia","kind":"drill","level":"mbbs","review":"ai_drafted","timeLimitSec":600,"title":{"en":"Eclampsia drill","hi":"एक्लेम्पसिया ड्रिल"},"scenario":{"en":"A 22-year-old primigravida at 36 weeks with severe pre-eclampsia starts a generalised tonic-clonic seizure on the antenatal ward. Teaching scenario, not a real patient.","hi":"36 सप्ताह की 22 वर्षीय पहली बार गर्भवती महिला, जिसे गंभीर प्री-एक्लेम्पसिया है, प्रसव-पूर्व वार्ड में पूरे शरीर के दौरे (टॉनिक-क्लोनिक) में है। यह शिक्षण परिदृश्य है, असली मरीज़ नहीं।"},"sources":[{"label":"FOGSI-Gestosis-ICOG. Hypertensive Disorders in Pregnancy: Good Clinical Practice Recommendations 2019","url":"https://icogonline.org/wp-content/uploads/pdf/gcpr/hdp_fogsi_gestosis_icog_gcpr_2019.pdf"},{"label":"StewardMD Clinical Protocols: Pre-eclampsia, severe hypertension and eclampsia, India (FOGSI)","path":"kb/clinical-protocols/pre-eclampsia-eclampsia-india.json"},{"label":"WHO. Managing Complications in Pregnancy and Childbirth, 2nd edition (2017)","url":"https://iris.who.int/server/api/core/bitstreams/3bda1306-da5d-487d-b2ad-aff995112a7a/content"}],"stages":[{"id":"airway","src":0,"timeSec":30,"prompt":{"en":"She is fitting now. First actions?","hi":"उसे अभी दौरा पड़ रहा है। पहले क्या करें?"},"options":[{"id":"a","correct":true,"critical":true,"text":{"en":"Call for help, turn her onto her side, protect her from injury, mouth gag and suction to keep the airway clear.","hi":"मदद बुलाएँ, उसे करवट पर लिटाएँ, चोट से बचाएँ, माउथ गैग और सक्शन से वायुमार्ग साफ़ रखें।"},"feedback":{"en":"FOGSI: call for help; airway with lateral decubitus position, mouth gag, avoid injury.","hi":"FOGSI: मदद बुलाएँ; करवट की स्थिति, माउथ गैग से वायुमार्ग, चोट से बचाव।"}},{"id":"b","correct":false,"text":{"en":"Hold her flat on her back and restrain her limbs.","hi":"उसे पीठ के बल सीधा रखें और हाथ-पैर बाँध दें।"},"feedback":{"en":"Supine risks aspiration and restraint causes injury. Lateral position, protect from injury.","hi":"पीठ के बल रखने से साँस में उल्टी जाने का खतरा और बाँधने से चोट होती है। करवट पर रखें, चोट से बचाएँ।"}},{"id":"c","correct":false,"text":{"en":"Give diazepam IV first to stop the fit.","hi":"दौरा रोकने के लिए पहले डायज़ेपाम IV दें।"},"feedback":{"en":"Magnesium sulphate is the first-choice drug for eclampsia, not diazepam.","hi":"एक्लेम्पसिया में पहली पसंद की दवा मैग्नीशियम सल्फेट है, डायज़ेपाम नहीं।"}}]},{"id":"breathing","src":0,"timeSec":60,"prompt":{"en":"The fit has stopped. Breathing and circulation?","hi":"दौरा रुक गया है। साँस और परिसंचरण?"},"options":[{"id":"a","correct":true,"text":{"en":"Oxygen and suction, pulse oximetry aiming above 96%, IV access, send HDP laboratory tests, Ringer lactate or saline at 80 mL/h, Foley catheter.","hi":"ऑक्सीजन और सक्शन, पल्स ऑक्सीमेट्री 96% से ऊपर का लक्ष्य, IV लाइन, HDP जाँचें भेजें, रिंगर लैक्टेट या सलाइन 80 mL/h, फ़ोली कैथेटर।"},"feedback":{"en":"FOGSI breathing and circulation steps. Keep fluids at 80 mL/h: no fluid loading, to avoid pulmonary oedema.","hi":"FOGSI के साँस और परिसंचरण कदम। फ़्लूइड 80 mL/h रखें: फेफड़ों में पानी से बचने के लिए ज़्यादा फ़्लूइड नहीं।"}},{"id":"b","correct":false,"text":{"en":"Give a 1 L fluid bolus to protect the kidneys.","hi":"गुर्दों की रक्षा के लिए 1 L फ़्लूइड बोलस दें।"},"feedback":{"en":"Liberal fluids cause pulmonary oedema in pre-eclampsia. Restrict to 80 mL/h.","hi":"प्री-एक्लेम्पसिया में ज़्यादा फ़्लूइड से फेफड़ों में पानी भरता है। 80 mL/h तक सीमित रखें।"}}]},{"id":"loading","src":0,"timeSec":90,"prompt":{"en":"Magnesium sulphate loading dose (Pritchard), using 50% w/v ampoules of 1 g each?","hi":"मैग्नीशियम सल्फेट लोडिंग खुराक (प्रिचर्ड), 1 g वाली 50% w/v एम्प्यूल से?"},"options":[{"id":"a","correct":true,"critical":true,"text":{"en":"4 g slow IV (4 ampoules plus 12 mL distilled water, 20 mL of 20%) at 1 g per minute, plus 5 g of 50% deep IM into each buttock with 0.5 mL of 2% lignocaine: 14 g in total.","hi":"4 g धीमे IV (4 एम्प्यूल और 12 mL डिस्टिल्ड पानी, 20% का 20 mL) 1 g प्रति मिनट की दर से, साथ में हर नितंब में 50% का 5 g गहरा IM, 0.5 mL 2% लिग्नोकेन के साथ: कुल 14 g।"},"feedback":{"en":"FOGSI Pritchard loading dose. Keep 10% calcium gluconate at the bedside.","hi":"FOGSI प्रिचर्ड लोडिंग खुराक। 10% कैल्शियम ग्लूकोनेट बिस्तर के पास रखें।"}},{"id":"b","correct":false,"text":{"en":"2 g IV only, then watch.","hi":"केवल 2 g IV, फिर निगरानी।"},"feedback":{"en":"Under-dosed. The Pritchard loading dose is 14 g in total.","hi":"खुराक कम है। प्रिचर्ड लोडिंग कुल 14 g है।"}},{"id":"c","correct":false,"text":{"en":"Phenytoin loading dose instead.","hi":"इसकी जगह फ़िनाइटोइन लोडिंग।"},"feedback":{"en":"Magnesium sulphate is the safest first-choice drug for eclampsia.","hi":"एक्लेम्पसिया में मैग्नीशियम सल्फेट सबसे सुरक्षित पहली पसंद है।"}}]},{"id":"bp","src":0,"timeSec":90,"vitals":{"bp":"168/112","pulse":96},"prompt":{"en":"BP is 168/112 mmHg. She has no asthma or heart disease. Control it how?","hi":"BP 168/112 mmHg है। उसे अस्थमा या हृदय रोग नहीं है। इसे कैसे नियंत्रित करें?"},"options":[{"id":"a","correct":true,"critical":true,"text":{"en":"Nifedipine 10 to 30 mg orally, swallowed whole, repeat in 30 to 45 minutes if needed (maximum 120 mg); or labetalol 10 to 20 mg slow IV, then 20 to 80 mg every 20 to 30 minutes (maximum 300 mg).","hi":"निफ़ेडिपिन 10 से 30 mg मुँह से, पूरी निगलें, ज़रूरत हो तो 30 से 45 मिनट बाद दोहराएँ (अधिकतम 120 mg); या लेबेटालॉल 10 से 20 mg धीमे IV, फिर हर 20 से 30 मिनट पर 20 से 80 mg (अधिकतम 300 mg)।"},"feedback":{"en":"FOGSI rapid-control drugs. Treat 160/110 or more within 1 hour; lower BP promptly but gradually.","hi":"FOGSI की तेज़ नियंत्रण दवाएँ। 160/110 या अधिक का इलाज 1 घंटे के भीतर; BP जल्दी पर धीरे-धीरे घटाएँ।"}},{"id":"b","correct":false,"text":{"en":"Nifedipine 10 mg sublingually.","hi":"निफ़ेडिपिन 10 mg जीभ के नीचे।"},"feedback":{"en":"Never sublingual: the BP can crash and compromise the fetus.","hi":"जीभ के नीचे कभी नहीं: BP अचानक गिर सकता है और भ्रूण को नुकसान हो सकता है।"}},{"id":"c","correct":false,"text":{"en":"Leave BP alone until after delivery.","hi":"प्रसव के बाद तक BP को छोड़ दें।"},"feedback":{"en":"Severe hypertension risks stroke; treat it now.","hi":"गंभीर हाइपरटेंशन से स्ट्रोक का खतरा है; अभी इलाज करें।"}}]},{"id":"maintenance","src":0,"timeSec":60,"vitals":{"rr":18,"patellarReflex":"present","urine4hMl":120},"prompt":{"en":"Four hours later: respiratory rate 18/min, knee jerks present, urine 120 mL in the last 4 hours. Maintenance?","hi":"4 घंटे बाद: साँस की दर 18/min, घुटने की रिफ़्लेक्स मौजूद, पिछले 4 घंटे में मूत्र 120 mL। मेंटेनेंस?"},"options":[{"id":"a","correct":true,"critical":true,"text":{"en":"All three checks pass: give 5 g of 50% deep IM into the alternate buttock, and check again before every dose.","hi":"तीनों जाँचें ठीक हैं: दूसरे नितंब में 50% का 5 g गहरा IM दें, और हर खुराक से पहले फिर जाँचें।"},"feedback":{"en":"FOGSI gives maintenance only if respiratory rate is above 16/min, patellar reflexes are present and urine is above 100 mL in the last 4 hours.","hi":"FOGSI मेंटेनेंस तभी देता है जब साँस की दर 16/min से अधिक, पटेलर रिफ़्लेक्स मौजूद और पिछले 4 घंटे में मूत्र 100 mL से अधिक हो।"}},{"id":"b","correct":false,"text":{"en":"Give the dose without checking; she looks well.","hi":"बिना जाँचे खुराक दें; वह ठीक दिख रही है।"},"feedback":{"en":"Every maintenance dose needs the three checks first.","hi":"हर मेंटेनेंस खुराक से पहले तीनों जाँचें ज़रूरी हैं।"}},{"id":"c","correct":false,"text":{"en":"Repeat the 4 g IV loading dose.","hi":"4 g IV लोडिंग खुराक दोहराएँ।"},"feedback":{"en":"Maintenance on Pritchard is 5 g deep IM every 4 hours, not a new loading dose.","hi":"प्रिचर्ड में मेंटेनेंस हर 4 घंटे पर 5 g गहरा IM है, नई लोडिंग नहीं।"}}]},{"id":"toxicity","src":0,"timeSec":60,"vitals":{"rr":10,"patellarReflex":"absent"},"prompt":{"en":"Later she is drowsy, respiratory rate 10/min, knee jerks absent. What do you do?","hi":"बाद में वह उनींदी है, साँस की दर 10/min, घुटने की रिफ़्लेक्स अनुपस्थित। आप क्या करेंगे?"},"options":[{"id":"a","correct":true,"critical":true,"text":{"en":"Stop magnesium, give oxygen, intubate if needed, and give 10 mL of 10% calcium gluconate slow IV over 10 minutes with ECG monitoring.","hi":"मैग्नीशियम बंद करें, ऑक्सीजन दें, ज़रूरत हो तो इंट्यूबेट करें, और ECG निगरानी के साथ 10% कैल्शियम ग्लूकोनेट 10 mL धीमे IV 10 मिनट में दें।"},"feedback":{"en":"FOGSI management of magnesium overdose.","hi":"मैग्नीशियम अधिकता का FOGSI प्रबंधन।"}},{"id":"b","correct":false,"text":{"en":"Give the next maintenance dose on schedule.","hi":"अगली मेंटेनेंस खुराक समय पर दें।"},"feedback":{"en":"The checks fail: this is toxicity. Stop magnesium.","hi":"जाँचें विफल हैं: यह विषाक्तता है। मैग्नीशियम बंद करें।"}},{"id":"c","correct":false,"text":{"en":"Give naloxone.","hi":"नालोक्सोन दें।"},"feedback":{"en":"The antidote for magnesium is calcium gluconate.","hi":"मैग्नीशियम का प्रतिरोधी कैल्शियम ग्लूकोनेट है।"}}]},{"id":"delivery","src":0,"timeSec":90,"prompt":{"en":"She is now stable: no further fits, BP controlled. She is 36 weeks. Plan?","hi":"वह अब स्थिर है: और दौरे नहीं, BP नियंत्रित। वह 36 सप्ताह की है। योजना?"},"options":[{"id":"a","correct":true,"critical":true,"text":{"en":"Deliver now that she is stabilised: vaginal birth if attainable in a reasonable time, caesarean for obstetric indications; continue magnesium for 24 hours after delivery or the last fit, whichever is later.","hi":"स्थिर होने पर अब प्रसव कराएँ: उचित समय में संभव हो तो योनि प्रसव, प्रसूति कारणों पर सिज़ेरियन; मैग्नीशियम प्रसव या अंतिम दौरे, जो बाद में हो, के 24 घंटे बाद तक जारी रखें।"},"feedback":{"en":"FOGSI: in eclampsia, deliver once the mother is stabilised.","hi":"FOGSI: एक्लेम्पसिया में माँ के स्थिर होते ही प्रसव कराएँ।"}},{"id":"b","correct":false,"text":{"en":"Caesarean section during the fit.","hi":"दौरे के दौरान सिज़ेरियन।"},"feedback":{"en":"Stabilise first: stop fits, control BP, oxygenate. Then deliver.","hi":"पहले स्थिर करें: दौरे रोकें, BP नियंत्रित करें, ऑक्सीजन दें। फिर प्रसव।"}},{"id":"c","correct":false,"text":{"en":"Continue the pregnancy to 37 weeks.","hi":"गर्भावस्था 37 सप्ताह तक जारी रखें।"},"feedback":{"en":"Eclampsia is an indication to deliver once stabilised, whatever the gestation.","hi":"एक्लेम्पसिया में स्थिर होने पर प्रसव ज़रूरी है, गर्भकाल चाहे जो हो।"}}]},{"id":"thirdstage","src":1,"timeSec":60,"prompt":{"en":"She delivers vaginally. Which uterotonic for the third stage?","hi":"उसका योनि प्रसव हो गया। तीसरे चरण के लिए कौन सा यूटेरोटोनिक?"},"options":[{"id":"a","correct":true,"next":"end","text":{"en":"Oxytocin, with active management of the third stage; avoid methylergometrine.","hi":"ऑक्सीटोसिन, तीसरे चरण के सक्रिय प्रबंधन के साथ; मिथाइलअर्गोमेट्रिन से बचें।"},"feedback":{"en":"Women with pre-eclampsia tolerate blood loss poorly, and methylergometrine is contraindicated in hypertension.","hi":"प्री-एक्लेम्पसिया वाली महिलाएँ रक्तस्राव कम सह पाती हैं, और हाइपरटेंशन में मिथाइलअर्गोमेट्रिन वर्जित है।"}},{"id":"b","correct":false,"next":"end","text":{"en":"Methylergometrine 0.2 mg IM.","hi":"मिथाइलअर्गोमेट्रिन 0.2 mg IM।"},"feedback":{"en":"Contraindicated in hypertension, pre-eclampsia and eclampsia.","hi":"हाइपरटेंशन, प्री-एक्लेम्पसिया और एक्लेम्पसिया में वर्जित।"}}]}]});
